def filter_nulls(items):
    return [item for item in items if item is not None]


def normalize_strings(items):
    return [item.strip().lower() if isinstance(item, str) else item for item in items]


def deduplicate(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def sort_items(items):
    return sorted(items)


def pipe(data, *transforms):
    for transform in transforms:
        data = transform(data)
    return data


class Pipeline:
    def __init__(self, data):
        self.data = data

    def run(self):
        return pipe(self.data, filter_nulls, normalize_strings, deduplicate, sort_items)
